<?php
/*
 | SHULETECH UI - generates backend/dist/css/shuletech-font.css
 | Run from a terminal:  C:\xampp\php\php.exe application\third_party\gen_font_css.php
 | Re-run after any theme/CSS update so weights and icon fonts stay correct.
 */
if (PHP_SAPI !== 'cli') { exit('CLI only'); }

$root = realpath(__DIR__ . '/../../') . '/';
$cssFiles = [];
$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root . 'backend', FilesystemIterator::SKIP_DOTS));
foreach ($it as $f) {
    if (strtolower($f->getExtension()) === 'css' && $f->getFilename() !== 'shuletech-font.css') {
        $cssFiles[] = $f->getPathname();
    }
}

function css_rules($path)
{
    $css = preg_replace('#/\*.*?\*/#s', '', file_get_contents($path));
    preg_match_all('#([^{}@]+)\{([^{}]*)\}#', $css, $m, PREG_SET_ORDER);
    return $m;
}

$iconLib   = '#(font-awesome|all\.min|ionicons|bootstrap-icons|lucide|flag-icon|glyphicon|dropify|fullcalendar\.print)#i';
$weights   = ['Roboto-Black' => 900, 'Roboto-Bold' => 700, 'Roboto-Medium' => 500, 'Roboto-Regular' => 400,
              'Roboto-Light' => 300, 'Roboto-Thin' => 200, 'var(--font-primary)' => 700];
$iconFontRe = '/font-family\s*:\s*([^;]*(FontAwesome|Font Awesome|Glyphicons|Ionicons|bootstrap-icons|lucide|dropify|Material Icons)[^;]*)/i';

$weightRules = [];
$restore     = [];

// Elements that draw a glyph through ::before/::after (e.g. ".main-header .sidebar-toggle:before{content:"\f0c9"}").
$drawsGlyph = [];
foreach ($cssFiles as $path) {
    foreach (css_rules($path) as $r) {
        if (!preg_match('/content\s*:\s*["\']\\\\[0-9a-f]{3,5}["\']/i', $r[2])) {
            continue;
        }
        foreach (explode(',', $r[1]) as $one) {
            $one = trim(preg_replace('/\s+/', ' ', $one));
            if (preg_match('/^(.*?)::?(before|after)$/i', $one, $pm)) {
                $drawsGlyph[trim($pm[1])] = true;
            }
        }
    }
}
// Real icon classes / icon tags: always keep their icon font.
$isIconSelector = function ($sel) use ($drawsGlyph) {
    return isset($drawsGlyph[$sel])
        || preg_match('/(^|\s|\.)(glyphicon|ion|ionicons|fa|bi|lucide)$/i', $sel)
        || preg_match('/\[class[\^\*]="\s*(icon|fa|bi|ion)-"\]$/i', $sel)
        || preg_match('/(^|\s)i$/', $sel);
};

foreach ($cssFiles as $path) {
    $isIconLib = preg_match($iconLib, basename($path));
    foreach (css_rules($path) as $r) {
        $selList = trim(preg_replace('/\s+/', ' ', $r[1]));
        $decl    = $r[2];
        if ($selList === '' || preg_match('/^(from|to|\d+%)/', $selList)) {
            continue;
        }
        // 1) icon-font elements (not pseudo-elements) must keep their icon font
        if (preg_match($iconFontRe, $decl, $im)) {
            $fam = trim(str_ireplace('!important', '', $im[1]));
            foreach (explode(',', $selList) as $one) {
                $one = trim($one);
                // skip pseudo/hover selectors, leftovers of @font-face blocks, and text elements that
                // merely share a rule with an icon (e.g. .sidebar-session grouped with .sidebar-toggle)
                if ($one !== '' && strpos($one, ':') === false && $one !== 'font-face' && $isIconSelector($one)) {
                    $restore[$fam][$one] = true;
                }
            }
            continue;
        }
        // 2) rules whose boldness came from a named Roboto file keep that weight
        if ($isIconLib || !preg_match('/font-family\s*:\s*([^;]+)/i', $decl, $fm) || preg_match('/font-weight\s*:/i', $decl)) {
            continue;
        }
        foreach ($weights as $name => $w) {
            if (stripos($fm[1], $name) !== false) {
                $weightRules[$w][$selList] = true;
                break;
            }
        }
    }
}
krsort($weightRules);

$not = ':not(i):not(.fa):not([class^="fa-"]):not([class*=" fa-"]):not(.fas):not(.far):not(.fab):not(.fa-solid):not(.fa-regular):not(.fa-brands)'
     . ':not(.glyphicon):not([class*="glyphicon-"]):not(.ion):not([class^="ion-"]):not([class*=" ion-"]):not(.bi):not([class^="bi-"]):not([class*=" bi-"])'
     . ':not([class^="icon-"]):not([class*=" icon-"]):not([class*="lucide"]):not(.material-icons):not([class*="dropify-font"]):not(.flag-icon):not(.caret)';

$out  = "/*\n * SHULETECH UI: system-wide font (Bricolage Grotesque).\n";
$out .= " * GENERATED by application/third_party/gen_font_css.php - do not edit by hand, re-run the generator.\n";
$out .= " * Must be the LAST stylesheet on every page shell.\n */\n";
$out .= ":root {\n  --st-font: 'Bricolage Grotesque', 'Segoe UI', system-ui, -apple-system, Roboto, 'Helvetica Neue', Arial, sans-serif;\n  --font-primary: var(--st-font);\n}\n\n";
$out .= "/* Zero specificity (:where) so any icon rule below can win. */\n";
$out .= ":where(body, body *$not) {\n  font-family: var(--st-font) !important;\n}\n";
$out .= ":where(body input, body select, body textarea, body button, body .btn, body .form-control) {\n  font-family: var(--st-font) !important;\n}\n\n";

$out .= "/* Keep the weights the old named fonts (Roboto-Bold, Roboto-Medium...) provided. */\n";
$nW = 0;
foreach ($weightRules as $w => $sels) {
    foreach (array_chunk(array_keys($sels), 40) as $c) {
        $out .= implode(",\n", $c) . " {\n  font-weight: $w;\n}\n";
        $nW  += count($c);
    }
}

$out .= "\n/* Elements that ARE icons through their own font (e.g. .sidebar-toggle) keep that icon font. */\n";
$nR = 0;
foreach ($restore as $fam => $sels) {
    foreach (array_chunk(array_keys($sels), 40) as $c) {
        $out .= implode(",\n", $c) . " {\n  font-family: $fam !important;\n}\n";
        $nR  += count($c);
    }
}

file_put_contents($root . 'backend/dist/css/shuletech-font.css', $out);
echo "scanned " . count($cssFiles) . " css files; $nW weight rules; $nR icon-font selectors restored; " . strlen($out) . " bytes\n";
